import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void conv1d_kernel(
    const half* __restrict__ input,
    const half* __restrict__ weight,
    half* __restrict__ output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int dilation
) {
    int batch_idx = blockIdx.x;
    int out_ch_idx = blockIdx.y;
    int out_pos_idx = blockIdx.z * blockDim.x + threadIdx.x;

    if (batch_idx >= batch_size || out_ch_idx >= out_channels || out_pos_idx >= output_length) {
        return;
    }

    // Shared memory for input window
    extern __shared__ half shared_input[];

    half sum = __hzero();

    // For each input channel
    for (int in_ch = 0; in_ch < in_channels; ++in_ch) {
        // Load input window into shared memory
        int input_start = batch_idx * in_channels * input_length + 
                         in_ch * input_length + 
                         out_pos_idx * stride;

        // Load kernel weights
        const half* kernel_ptr = weight + out_ch_idx * in_channels * kernel_size + 
                                in_ch * kernel_size;

        // Perform convolution
        for (int k = 0; k < kernel_size; ++k) {
            int input_pos = input_start + k * dilation;
            if (input_pos >= 0 && input_pos < input_length) {
                sum = __hadd(sum, __hmul(input[input_pos], kernel_ptr[k]));
            }
        }
    }

    // Store result
    int output_idx = batch_idx * out_channels * output_length + 
                    out_ch_idx * output_length + 
                    out_pos_idx;
    output[output_idx] = sum;
}

// Wrapper function to launch kernel
void launch_conv1d_kernel(
    const half* input,
    const half* weight,
    half* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int dilation
) {
    dim3 grid(batch_size, out_channels, (output_length + 255) / 256);
    dim3 block(256);
    size_t shared_mem_size = input_length * sizeof(half);

    conv1d_kernel<<<grid, block, shared_mem_size>>>(
        input, weight, output, batch_size, in_channels, out_channels,
        input_length, output_length, kernel_size, stride, dilation
    );
}
"""

# Python wrapper class
class ModelNew(torch.nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.dilation = dilation
        self.bias = bias

        # Initialize weights
        self.weight = torch.nn.Parameter(torch.randn(out_channels, in_channels, kernel_size, dtype=torch.float16))
        if bias:
            self.bias = torch.nn.Parameter(torch.randn(out_channels, dtype=torch.float16))
        else:
            self.register_parameter('bias', None)

        # Compile CUDA extension
        self.conv_module = load_inline(
            name="conv1d_cuda",
            cpp_sources=cuda_source,
            cuda_sources=cuda_source,
            functions=["launch_conv1d_kernel"],
            verbose=True
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        batch_size, _, input_length = x.shape

        # Calculate output length
        output_length = (input_length + 2 * 0 - (self.dilation * (self.kernel_size - 1) + 1)) // self.stride + 1

        # Prepare output tensor
        output = torch.empty(batch_size, self.out_channels, output_length, dtype=torch.float16, device=x.device)

        # Launch CUDA kernel
        self.conv_module.launch_conv1d_kernel(
            x.contiguous().data_ptr(),
            self.weight.data_ptr(),
            output.data_ptr(),
            batch_size,
            self.in_channels,
            self.out_channels,
            input_length,
            output_length,
            self.kernel_size,
            self.stride,
            self.dilation
        )

        # Add bias if present
        if self.bias is not None:
            output += self.bias.view(1, -1, 1)

        return output

